def process(greece_cities) -> pd.DataFrame:
    ranks = []
    for rank_str in greece_cities['Barrington Atlas Rank']:
        if 'or' in str(rank_str):
            parts = str(rank_str).split(' or ')
            num1 = float(parts[0].strip())
            num2 = float(parts[1].strip())
            avg_rank = (num1 + num2) / 2
            ranks.append(avg_rank)
        else:
            ranks.append(float(rank_str))

    avg = sum(ranks) / len(ranks)
    return pd.DataFrame({'average_rank': [round(avg, 4)]})
